// Russian texts of catalog.mjs: [English text, Russian text], in catalog order. The English side must match the T() text
// exactly (the build names any text without a translation and any entry whose English text changed or went away).
// Terms follow the app (src/Filee.App/Assets/i18n/ru.json): пресет (preset), движок / дополнительный движок (engine,
// optional engine), круг форматов (donut toolbar), папки наблюдения (watch folders), зона перетаскивания (drop zone),
// «Конвертировать с Filee», Настройки → Движки (Settings → Engines), preset names as in the app.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `видео и аудио, извлечение субтитров и сохранение в HEIC`],
  [`older office formats such as DOC, PPT and ODT`,
    `старые офисные форматы вроде DOC, PPT и ODT`],
  [`rare e-book formats and MOBI/AZW3 output`,
    `редкие форматы электронных книг и сохранение в MOBI/AZW3`],
  [`EPS and PostScript`,
    `EPS и PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc и другая разметка, Word → Markdown и Markdown → слайды`],

  // Options
  [`quality`, `качество`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Настраиваемое качество для JPG, WEBP и AVIF: по умолчанию JPG сохраняется с качеством 90 %, а пресет JPG 70 % даёт файлы поменьше.`],
  [`resize`, `изменение размера`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Изменение размера при конвертации: в процентах (например, вдвое меньше) или по максимальной длинной стороне.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `DPI, записываемое в изображение, например 300 для печати.`],
  [`grayscale`, `оттенки серого`],
  [`A grayscale preset makes black-and-white copies.`,
    `Пресет «Оттенки серого» делает чёрно-белые копии.`],
  [`metadata`, `метаданные`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Метаданные (EXIF, XMP, цветовой профиль) по умолчанию сохраняются, а ради конфиденциальности их можно удалить.`],
  [`ICO sizes`, `размеры ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `По умолчанию файл ICO содержит размеры 256, 128, 64, 48, 32 и 16 px; набор размеров меняется в пресете.`],
  [`TIFF compression`, `сжатие TIFF`],
  [`TIFF compression can be chosen (LZW by default).`,
    `Сжатие TIFF можно выбрать (по умолчанию LZW).`],
  [`white background`, `белый фон`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `В JPG нет прозрачности, поэтому прозрачные области заливаются белым.`],
  [`merge into one PDF`, `объединение в один PDF`],
  [`The merge preset combines all dropped files into one PDF.`,
    `Пресет «Объединить PDF» собирает все отпущенные файлы в один PDF.`],
  [`split pages`, `разделение на страницы`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `Пресет «Разделить PDF» сохраняет каждую страницу отдельным PDF во вложенную папку.`],
  [`rotate & flip`, `поворот и отражение`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `Пресеты «Повернуть» и «Отразить» поворачивают изображения влево, вправо или на 180° и зеркально отражают их — с учётом ориентации, записанной в самом фото.`],
  [`Trace to SVG`, `обводка в SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Два пресета превращают картинку в векторные фигуры: «Обвести в SVG» — до 64 цветов, «Штриховой рисунок в SVG» — чёрным, для логотипов, подписей и сканов. Другие программы не нужны.`],
  [`remove background`, `удаление фона`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `Пресет «Убрать фон» делает однотонный фон прозрачным: бумагу под подписью или печатью, фон логотипа.`],
  [`page ranges`, `диапазоны страниц`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Диапазоны вроде 1-3,5 ограничивают конвертацию нужными страницами.`],
  [`render DPI`, `DPI отрисовки`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `По умолчанию страницы отрисовываются в 150 DPI; для печати выберите 300 DPI.`],
  [`one long image`, `одна длинная картинка`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `Пресет «Длинная картинка» складывает все страницы в одно высокое изображение, например чтобы выложить документ целиком.`],
  [`compress PDF`, `сжатие PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `Пресет «Сжать PDF» уменьшает файл, оставляя его PDF: картинки уменьшаются до 72, 150 или 300 dpi, фото пересохраняются в JPEG, а текст, шрифты, ссылки, закладки и формы остаются как были. PDF, который не получается уменьшить, не меняется. Если установлен Ghostscript, Filee попробует сжать и им и оставит меньший результат.`],
  [`a picture per slide`, `картинка на слайд`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `«PPTX (слайды)» помещает изображение каждой страницы на отдельный слайд размером со страницу, а текст страницы — в заметки докладчика. Слайды выглядят точно как PDF, но редактировать их нельзя; для редактируемого текста конвертируйте в DOCX.`],
  [`vector PDF`, `векторный PDF`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `PDF остаётся векторным, поэтому он чёткий при любом масштабе и в печати.`],
  [`editable`, `редактируемый`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `В результате настоящий текст и абзацы, которые можно редактировать, а не картинки страниц.`],
  [`attachments as ZIP`, `вложения в ZIP`],
  [`Attachments can be saved separately as one ZIP.`,
    `Вложения можно сохранить отдельно, одним ZIP.`],
  [`one CSV per sheet`, `один CSV на лист`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Из книги с несколькими листами получается по одному CSV на лист.`],
  [`layout kept`, `вёрстка сохраняется`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Сохраняются размер страницы и поля, колонтитулы с номерами страниц, таблицы, текстовые поля, фигуры и картинки.`],
  [`no Office needed`, `без Office`],
  [`No Microsoft Office or LibreOffice needed.`,
    `Microsoft Office и LibreOffice не нужны.`],
  [`no Hancom Office needed`, `без Hancom Office`],
  [`No Hancom Office and no approval dialog.`,
    `Без Hancom Office и без запросов на подтверждение.`],
  [`no AutoCAD needed`, `без AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`,
    `AutoCAD и просмотрщик DWG не нужны.`],
  [`no re-encoding`, `без перекодирования`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Если новый формат может принять видео и звук как есть (MOV с iPhone → MP4), они только перепаковываются: без потери качества, с сохранением HDR, за секунды.`],
  [`720p option`, `вариант 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `Пресет MP4 720p уменьшает большие видео, чтобы ими было удобно делиться.`],
  [`extract audio`, `извлечение звука`],
  [`Only the sound is saved, without the video track.`,
    `Сохраняется только звук, без видеодорожки.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `Пресет MP3 128k даёт файлы поменьше — то, что нужно для записей речи.`],
  [`extract`, `распаковка`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Пресет «Распаковать» вместо этого распаковывает архив в папку.`],
  [`pack into one ZIP`, `упаковка в один ZIP`],
  [`Any selection of files can be packed into one ZIP.`,
    `Любой набор файлов можно упаковать в один ZIP.`],
  [`DRM-free books`, `книги без DRM`],
  [`Works with DRM-free books only.`,
    `Работает только с книгами без DRM.`],
  [`ALAC in M4A`, `ALAC в M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`,
    `M4A может содержать не только AAC, но и ALAC без потерь.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `Видеопресеты умеют кодировать в HEVC (H.265) или AV1 ради файлов поменьше, сохраняя 10-битное видео и HDR.`],
  [`hardware encoding`, `аппаратное кодирование`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Включите «Аппаратное ускорение» в видеопресете, чтобы кодировать H.264 и HEVC на видеочипе (NVENC, Quick Sync, AMF, VideoToolbox или VA-API): намного быстрее и экономнее, а при том же качестве файл чуть больше. По умолчанию выключено; без подходящего чипа видео кодируется как обычно.`],
  [`every frame`, `каждый кадр`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Обычно из видео получается один стоп-кадр. Пресеты «Кадры в картинки» или параметр «Сохранить каждый кадр видео» в пресете PNG или JPG сохраняют каждый кадр (или каждый N-й) картинками в папку рядом с видео.`],
  [`extract subtitles`, `извлечение субтитров`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `Пресет «Извлечь субтитры» в круге для видео сохраняет первую текстовую дорожку субтитров в SRT.`],
  [`saved as UTF-8`, `сохранение в UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Результат сохраняется в UTF-8. Корейские файлы в CP949 (EUC-KR) распознаются и читаются правильно.`],
  [`tables to CSV / Excel`, `таблицы в CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Табличные данные (список записей) также конвертируются в CSV и Excel и обратно.`],
  [`picture preview`, `превью картинкой`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG или JPG дают затенённое изображение модели спереди справа и сверху.`],
  [`colours and textures`, `цвета и текстуры`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Цвета, текстуры и материалы сохраняются, если целевой формат их поддерживает. STL хранит только форму.`],

  // Camera RAW
  [`Canon CR2 RAW photo`, `Фото RAW Canon CR2`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 — формат RAW, который зеркальные камеры Canon использовали много лет (новые модели Canon пишут CR3). В нём хранятся необработанные данные с матрицы, что даёт большой простор для обработки.`],
  [`Nikon NEF RAW photo`, `Фото RAW Nikon NEF`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF — формат RAW от Nikon, его используют зеркальные камеры Nikon и беззеркальные камеры серии Z. Как и другие RAW, он хранит необработанные данные с матрицы и в несколько раз больше JPG.`],

  // Images
  [`Images`, `Изображения`],
  [`images`, `изображения`],
  [`Photos and graphics, including iPhone HEIC, Photoshop PSD, camera RAW from all major brands, animated APNG and DICOM. Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Фото и графика, включая HEIC с iPhone, PSD из Photoshop, RAW с камер всех крупных брендов, анимированный APNG и DICOM. При конвертации можно изменить размер, повернуть, задать качество и DPI или удалить метаданные, а также обвести картинку в SVG.`],
  [`JPEG image`, `Изображение JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG — самый распространённый формат фотографий. Сжатие с потерями делает файлы маленькими, но каждое сохранение с пониженным качеством теряет часть деталей, а прозрачности в нём нет.`],
  [`PNG image`, `Изображение PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG — формат изображений без потерь с прозрачностью, идеальный для скриншотов, логотипов и графики с чёткими краями. Фото в PNG обычно намного больше, чем в JPG.`],
  [`WebP image`, `Изображение WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP — формат изображений от Google для веба. Он поддерживает сжатие с потерями и без, прозрачность и обычно меньше JPG и PNG, но некоторые редакторы и формы загрузки до сих пор его не принимают.`],
  [`AVIF image`, `Изображение AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF — современный формат изображений на основе видеокодека AV1. Он сжимает лучше JPG и WebP, но старые программы и устройства поддерживают его пока плохо.`],
  [`HEIC / HEIF image`, `Изображение HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF) — формат фото, который iPhone и iPad используют по умолчанию. Снимки часто вдвое меньше JPG, но многие программы Windows, сайты и старые устройства не умеют их открывать.`],
  [`GIF image / animation`, `Изображение / анимация GIF`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF — старый формат изображений, ограниченный 256 цветами, с поддержкой простой анимации. Он по-прежнему универсальный способ поделиться короткой беззвучной петлёй в чате, документе или отчёте об ошибке.`],
  [`Windows icon`, `Значок Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO — формат значков Windows. Один файл ICO содержит одну и ту же картинку в нескольких размерах (например, 16, 32, 48 и 256 пикселей), поэтому значок выглядит чётко везде — от панели задач до favicon сайта.`],
  [`Photoshop document`, `Документ Photoshop`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD — родной формат Adobe Photoshop. Он хранит слои, маски и корректирующие настройки, поэтому отлично подходит для редактирования, но большинство просмотрщиков и сайтов его не открывают.`],
  [`macOS icon`, `Значок macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS — формат значков macOS. Как и ICO, он объединяет несколько размеров одной картинки, вплоть до 1024×1024 для экранов Retina, и используется для значков программ на Mac.`],
  [`Camera RAW`, `RAW с камеры`],

  // Vector graphics
  [`Vector graphics`, `Векторная графика`],
  [`vector graphics`, `векторная графика`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, метафайлы Windows, Illustrator, EPS/PostScript и рисунки из CorelDRAW, Visio и LibreOffice Draw. SVG можно превратить и в DXF или DWG для CAD.`],
  [`SVG vector graphic`, `Векторная графика SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG — формат векторной графики на основе XML. Фигуры и текст остаются чёткими в любом размере, поэтому он идеален для логотипов и значков в вебе, но многие программы и формы загрузки принимают только растровые изображения.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS — векторный формат из полиграфии и дизайна, в нём часто отправляют в типографию логотипы и иллюстрации. Большинство современных программ не покажут его без интерпретатора PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `файлы AI, сохранённые с PDF-содержимым (по умолчанию в Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `Превращайте PDF в изображения, редактируемые документы Word или HWPX, слайды PowerPoint, текст или архив комикса, а также объединяйте, разделяйте, сжимайте и выбирайте страницы.`],
  [`PDF document`, `Документ PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF — стандарт для документов, которые должны везде выглядеть одинаково. Шрифты, вёрстка и картинки зафиксированы, и файл открывается на любом устройстве. Из-за этого же PDF трудно редактировать.`],
  [`one page`, `одна страница`],

  // Documents
  [`Documents`, `Документы`],
  [`documents`, `документы`],
  [`Word documents without Microsoft Office, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Документы Word без Microsoft Office, старые и редкие форматы текстовых редакторов с дополнительным движком LibreOffice и сохранённые письма (EML и Outlook MSG).`],
  [`Word document`, `Документ Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX — формат Microsoft Word начиная с Word 2007 (Office Open XML). Это самый распространённый формат редактируемых документов: отчётов, писем, бланков.`],
  [`Word 97–2003 document`, `Документ Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC — двоичный формат Word 97–2003. Его до сих пор выдают старые архивы, официальные бланки и устаревшие системы, но его вытесняет DOCX.`],
  [`E-mail message`, `Электронное письмо`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML — одно письмо, сохранённое файлом (формат MIME), с заголовками, текстом и вложениями. Его откроет большинство почтовых программ, включая Outlook и Thunderbird.`],
  [`Outlook message`, `Письмо Outlook`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG — файл, который сохраняет Microsoft Outlook, когда из него перетаскивают письмо. Открывает его только Outlook, поэтому на компьютере без Outlook или на телефоне его трудно прочитать.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `корейские HWP/HWPX`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Корейские документы Hancom Hangul без Hancom Office: HWP ↔ HWPX, в PDF, изображения, Word, текст, Markdown и HTML, а также HWPX из Word, Excel, PowerPoint, Markdown и PDF.`],
  [`Hangul document (HWP)`, `Документ Hangul (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP — формат документов Hancom Office Hangul (한글), стандартного текстового редактора корейских госучреждений, школ и многих компаний. За пределами Кореи его открывают немногие программы.`],
  [`Hangul document (HWPX)`, `Документ Hangul (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX — открытый формат Hancom Hangul на основе XML (OWPML, национальный стандарт Кореи KS X 6101). Корейские госучреждения переходят на него с двоичного HWP.`],

  // Spreadsheets
  [`Spreadsheets`, `Таблицы`],
  [`spreadsheets`, `таблицы`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Таблицы Excel, OpenDocument и CSV/TSV — в PDF с подгонкой под страницу, как в Excel, или друг в друга, без Excel.`],
  [`Excel workbook`, `Книга Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX — формат книг Microsoft Excel начиная с Excel 2007. Одна книга может содержать несколько листов с формулами, форматированием, диаграммами и картинками.`],
  [`Excel 97–2003 workbook`, `Книга Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS — двоичный формат книг Excel 97–2003. Его до сих пор выдают многие старые системы, банковские и бухгалтерские выгрузки.`],
  [`Comma-separated values`, `Значения, разделённые запятыми`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV — простой текст, где каждая строка — строка таблицы. Его читает любая табличная программа, база данных и язык программирования, но в нём нет форматирования, формул и нескольких листов.`],

  // Presentations
  [`Presentations`, `Презентации`],
  [`presentations`, `презентации`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint в PDF, изображения и HWPX без PowerPoint; старые PPT, ODP и Keynote — с дополнительным движком LibreOffice.`],
  [`PowerPoint presentation`, `Презентация PowerPoint`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX — формат Microsoft PowerPoint начиная с PowerPoint 2007. В нём хранятся слайды с текстом, картинками, фигурами, таблицами, заметками и анимацией.`],
  [`PowerPoint 97–2003 presentation`, `Презентация PowerPoint 97–2003`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT — двоичный формат PowerPoint 97–2003. Старые слайды лекций и архивные презентации часто до сих пор в PPT.`],

  // Text & markup
  [`Text & markup`, `Текст и разметка`],
  [`text and markup`, `текст и разметка`],
  [`Plain text, Markdown and HTML to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Простой текст, Markdown и HTML в PDF, Word, HWPX и EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter и другая разметка работают через дополнительный движок Pandoc, который также превращает Markdown в слайды PowerPoint.`],
  [`Plain text`, `Простой текст`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT — простой текст без форматирования, самый простой и переносимый формат документов. Различаться может только кодировка (UTF-8, UTF-16 или старая кодовая страница).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown — лёгкая разметка в простом тексте: # для заголовков, * для списков, ** для жирного. Её любят для заметок, файлов README и документации, и она читается даже без отрисовки.`],
  [`Web page (HTML)`, `Веб-страница (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML — язык веб-страниц. Сохранённый файл .html откроется в любом браузере, но его вид зависит от браузера и от подключённых стилей и картинок, которых офлайн может не оказаться.`],

  // Data
  [`Data`, `Данные`],
  [`data files`, `файлы данных`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML и XML друг в друга, а таблицы — в CSV и Excel и обратно. Контакты vCard в CSV и обратно, в том числе со старых телефонов. Ничего устанавливать не нужно.`],
  [`JSON data`, `Данные JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON — формат данных веба: объекты, списки, текст и числа в простом тексте. Его повсюду используют API, приложения и файлы настроек.`],
  [`YAML data`, `Данные YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML хранит те же данные, что и JSON, но записанные отступами вместо скобок. Конфигурации Docker, Kubernetes, конвейеров CI и многих приложений пишутся на YAML.`],
  [`vCard contacts`, `Контакты vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf) — стандартный файл контактов. Телефоны, Outlook, Google Контакты и iCloud экспортируют адресные книги в vCard, часто много контактов в одном файле.`],

  // E-books & comics
  [`E-books & comics`, `Электронные книги и комиксы`],
  [`e-books and comics`, `электронные книги и комиксы`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook и архивы комиксов (CBZ, CBR, CB7…) в PDF, EPUB, Word и другие форматы, а также KEPUB для читалок Kobo. Только книги без DRM.`],
  [`EPUB e-book`, `Электронная книга EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB — открытый стандарт электронных книг. Текст подстраивается под любой экран, его поддерживает большинство читалок и приложений для чтения; Kindle принимает EPUB через Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `Электронная книга Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI — старый формат электронных книг Mobipocket, который Amazon Kindle использовал много лет. Он ещё часто встречается в старых коллекциях книг, но Amazon перешёл на AZW3/KFX и EPUB.`],

  // Video
  [`Video`, `Видео`],
  [`video`, `видео`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Все распространённые форматы видео в MP4 (H.264, HEVC или AV1), WebM, MOV, MKV, AVI, GIF или APNG — с вариантом 720p, аппаратным кодированием на видеочипе, извлечением звука в MP3 или M4A и сохранением каждого кадра картинкой. Работает через дополнительный движок FFmpeg.`],
  [`MPEG-4 video`, `Видео MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Part 14) — самый совместимый формат видео. Он воспроизводится на телефонах, телевизорах, в браузерах и на любом видеосайте, обычно с видео H.264 или H.265 и звуком AAC.`],
  [`QuickTime movie`, `Видео QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV — формат видео QuickTime от Apple, его используют iPhone и Mac. Обычно внутри видео H.264 или HEVC, но некоторые редакторы, телевизоры и сайты лучше работают с MP4.`],
  [`Matroska video`, `Видео Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska) — гибкий открытый контейнер, в котором может быть много дорожек видео, звука и субтитров. Он популярен для фильмов и записей, но телефоны, телевизоры и редакторы воспроизводят его не всегда.`],
  [`WebM video`, `Видео WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM — открытый формат видео для браузеров (видео VP8/VP9 или AV1 со звуком Vorbis или Opus). Записи экрана и скачанные ролики часто в WebM, но многие редакторы и устройства ждут MP4.`],
  [`AVI video`, `Видео AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI — видеоконтейнер Microsoft из 1990-х. На видеокамерах, старых фотоаппаратах и в архивах до сих пор хранятся файлы AVI, часто большие и плохо поддерживаемые телефонами.`],
  [`one still frame or every frame`, `один стоп-кадр или каждый кадр`],

  // Audio
  [`Audio`, `Аудио`],
  [`audio`, `аудио`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Музыка, записи и голосовые заметки в MP3, M4A, WAV, FLAC, OGG, Opus, AAC или WavPack и TTA без потерь. APE, DSD и DTS тоже читаются. Работает через дополнительный движок FFmpeg.`],
  [`MP3 audio`, `Аудио MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 — классический формат сжатого звука. Его воспроизводит практически любой плеер, автомагнитола и телефон, поэтому это самый надёжный выбор, чтобы делиться музыкой, подкастами и записями.`],
  [`MPEG-4 audio`, `Аудио MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A — аудиофайл MPEG-4, обычно в AAC, его используют iTunes, диктофон iPhone и многие рекордеры. Он хорошо звучит при небольшом размере, но некоторые плееры и автомагнитолы принимают только MP3.`],
  [`WAV audio`, `Аудио WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV — несжатый звук (обычно PCM) для записи и монтажа. Он звучит точно как источник, но в качестве CD занимает около 10 МБ в минуту.`],
  [`FLAC lossless audio`, `Звук без потерь FLAC`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC — сжатие звука без потерь: файлы примерно вдвое меньше WAV при полном сохранении качества, поэтому это любимый формат музыкальных библиотек и hi-res-загрузок.`],

  // Subtitles
  [`Subtitles`, `Субтитры`],
  [`subtitles`, `субтитры`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML и MicroDVD друг в друга без каких-либо движков, с сохранением в UTF-8; SSA и SCC читаются. Корейские файлы SMI и SRT в CP949 читаются правильно. Субтитры из видео извлекает FFmpeg.`],
  [`SubRip subtitles`, `Субтитры SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) — самый распространённый файл субтитров: пронумерованные реплики со временем начала и конца и простым текстом. Его принимает почти любой плеер, редактор и видеосайт.`],
  [`Advanced SubStation Alpha subtitles`, `Субтитры Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha) — формат оформленных субтитров из фансабов аниме и Aegisub, со шрифтами, цветами, позициями и эффектами. Многие устройства и сайты принимают только простой SRT.`],
  [`WebVTT subtitles`, `Субтитры WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt) — формат субтитров для видео HTML5. Его используют веб-плееры, YouTube и платформы онлайн-курсов.`],
  [`SAMI subtitles (SMI)`, `Субтитры SAMI (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi) — похожий на HTML формат субтитров от Microsoft. В Корее это до сих пор классический файл субтитров, часто в старой кодировке CP949, которую новые плееры показывают кракозябрами.`],

  // Archives
  [`Archives`, `Архивы`],
  [`archives`, `архивы`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `Перепаковка и распаковка ZIP, 7Z, RAR, TAR, образов дисков и многих других архивов встроенным движком 7-Zip, а также упаковка любых файлов в один ZIP.`],
  [`ZIP archive`, `Архив ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP — универсальный формат архивов. Windows, macOS, телефоны и почти любая форма загрузки открывают его без дополнительных программ.`],
  [`7-Zip archive`, `Архив 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z — открытый формат архивов 7-Zip. Сжатие LZMA2 обычно даёт файлы меньше, чем ZIP, но открыть его может не каждая система и не каждый сайт.`],
  [`RAR archive`, `Архив RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR — закрытый формат архивов WinRAR, часто встречается у загрузок, разбитых на части. Свежие версии Windows 11 умеют открывать RAR, но не создавать, а многие инструменты принимают только ZIP.`],
  [`Any files`, `Любые файлы`],

  // CAD drawings
  [`CAD drawings`, `Чертежи CAD`],
  [`CAD drawings [in running text]`, `чертежи CAD`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `AutoCAD DWG и DXF: конвертация друг в друга или в PDF, SVG и PNG без AutoCAD.`],
  [`AutoCAD drawing`, `Чертёж AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG — родной формат чертежей AutoCAD и самый распространённый файл CAD в архитектуре и инженерии. Без AutoCAD или просмотрщика DWG его трудно открыть или передать.`],
  [`Drawing Exchange Format`, `Drawing Exchange Format`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format) — формат обмена чертежами CAD от Autodesk. Его читают лазерные резаки, программы ЧПУ и большинство CAD-программ, поэтому через него обычно и переносят чертежи между инструментами.`],

  // 3D models
  [`3D models`, `3D-модели`],
  [`3D models [in running text]`, `3D-модели`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF и PLY друг в друга — с цветами, текстурами и материалами, если формат их хранит, — а также в затенённую картинку PNG или JPG. Ничего устанавливать не нужно.`],
  [`glTF binary (GLB)`, `Двоичный glTF (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB — однофайловая версия glTF, 3D-формата для веба, AR и игровых движков. Сетки, материалы и текстуры упакованы в один компактный файл.`],
  [`STL 3D model`, `3D-модель STL`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL — классический файл для 3D-печати. Он хранит только треугольники формы, без цветов и единиц измерения, и его читает любой слайсер и любая CAD-программа.`],
  [`Wavefront OBJ model`, `Модель Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront) — текстовый 3D-формат, который открывает почти любая 3D-программа. Материалы и текстуры лежат рядом, в файле .mtl и картинках.`],

  // Fonts
  [`Fonts`, `Шрифты`],
  [`fonts`, `шрифты`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Компьютерные и веб-шрифты: TTF, OTF, WOFF, WOFF2 и EOT друг в друга.`],
  [`TrueType font`, `Шрифт TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType) — самый распространённый формат шрифтов в Windows и macOS. Установите шрифт, и он появится в любой программе.`],
  [`OpenType font`, `Шрифт OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType) — формат шрифтов от Adobe и Microsoft. Шрифты OpenType с контурами PostScript (CFF) часто встречаются среди профессиональных гарнитур и поддерживают такие возможности, как лигатуры.`],
  [`Web font (WOFF2)`, `Веб-шрифт (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 — сжатый формат веб-шрифтов, который поддерживают все современные браузеры. Обычно он примерно на 30 % меньше WOFF, поэтому страницы грузятся быстрее.`],

  // Camera RAW group (conversion pages)
  [`Camera RAW photo`, `Фото RAW с камеры`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Файлы RAW с камер (CR2, CR3, NEF, ARW, DNG, RAF, ORF и другие) хранят необработанные данные с матрицы. В них больше всего деталей для обработки, но они большие, и для просмотра нужны специальные программы.`],

  // Conversion guides: images
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `JPG — надёжный выбор, когда фото нужны сайту, старой программе Windows или человеку без iPhone. Целая пачка снимков HEIC конвертируется за раз, и каждый JPG сохраняется рядом со своим оригиналом.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Выбирайте PNG, если собираетесь дальше редактировать фото без лишнего круга сжатия JPG. PNG хранит без потерь, так что файлы будут в несколько раз больше исходного HEIC.`],
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `HEIC хранит фото примерно в половине места, которое нужно JPG при том же качестве, — так снимки сохраняет iPhone. Для сохранения в HEIC нужен бесплатный движок FFmpeg (около 100 МБ, скачивается в программе один раз). EXIF, цветовой профиль и ориентация сохраняются.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Картинки, сохранённые с сайтов, часто в WebP. Конвертация в PNG сохраняет полное качество и прозрачность, и результат подойдёт для любого редактора, презентации и документа.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Выбирайте JPG, если это фото и важен размер файла, например для форм загрузки, которые не принимают WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `Скриншоты и экспортированные фото в PNG могут весить много мегабайт. Фото в JPG обычно становятся намного меньше; для скриншотов с большим количеством текста и для логотипов PNG часто остаётся лучшим форматом.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Конвертация JPG в PNG не вернёт деталей, потерянных при сжатии JPG, но остановит дальнейшие потери: каждое следующее редактирование и сохранение будет без потерь. Конвертируйте до того, как ретушировать изображение или добавлять прозрачность в редакторе.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Изображения AVIF с современных сайтов и телефонов не открываются во многих старых программах, просмотрщиках и формах загрузки. JPG открывается везде, ценой чуть больших файлов.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `WebP идеален для сайтов: фото получаются намного меньше, чем в JPG, а графика сохраняет прозрачность. Пресет WEBP сохраняет с качеством 85 — хороший баланс для веба.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Сканы, чеки и фото документов часто нужно отправить одним PDF. Отпустите картинки на пресет «Объединить PDF», чтобы получить один файл, или на PDF, чтобы получить по PDF на каждую картинку. По умолчанию каждая страница принимает размер своей картинки.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Одного ICO хватает на все значки Windows — на рабочем столе, в Проводнике и на панели задач, — и он же подойдёт как favicon сайта. Для самого чёткого результата начинайте с квадратного PNG не меньше 256×256 px.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Чтобы сделать значок программы для Mac в Windows, обычно нужны дополнительные инструменты; Filee превращает PNG в ICNS напрямую. Берите квадратный PNG 1024×1024 px, чтобы размеры для Retina остались чёткими.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Покажите макет из Photoshop тем, у кого нет Photoshop: PNG показывает изображение в сохранённом виде, со сведёнными видимыми слоями и прозрачностью. Слои PNG хранить не умеет, так что для редактирования оставьте PSD.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee читает RAW-файлы Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One и других и проявляет их с настройками по умолчанию. Это быстрый способ получить со съёмки JPG, которыми можно поделиться; для творческой обработки сначала воспользуйтесь RAW-редактором.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Отпустите сразу все файлы CR2 с карты памяти: Filee сконвертирует их параллельно и сохранит каждый JPG рядом с его RAW-файлом. Новые камеры Canon пишут CR3 — его Filee тоже читает.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `Файлы NEF слишком большие и непривычные, чтобы отправлять их как есть. В JPG они превращаются в небольшие фото, которые откроются у кого угодно; для мессенджеров берите пресет JPG 70 % или «Вдвое меньше». Файлы NRW с камер Nikon Coolpix конвертируются так же.`],

  // Conversion guides: vector
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Многие программы, презентации и формы загрузки не принимают SVG. Filee отрисовывает векторный рисунок в PNG с прозрачностью; сжатые файлы SVGZ тоже подходят.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `SVG в PDF остаётся векторным: линии и текст чёткие при любом масштабе и в печати, а файл остаётся маленьким. Удобно, чтобы отправить логотипы и схемы в типографию или вставить их в документы.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS может показать только интерпретатор PostScript; Filee использует для этого Ghostscript. PDF сохраняет векторную графику, поэтому открывается где угодно и по-прежнему чётко печатается. Файлы PostScript (.ps) конвертируются так же.`],

  // Conversion guides: PDF
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Каждая страница становится отдельным JPG, так что из PDF на 10 страниц получится 10 картинок. Удобно для чатов, слайдов и постов в соцсетях, где принимают картинки, но не PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `PNG сохраняет текст и линии чёткими, без артефактов JPG, — это подходит для слайдов, схем, нот и страниц, которые вы хотите подписать или вставить в презентацию.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee превращает PDF в документ Word с настоящими абзацами, а не картинками страниц, так что можно исправить опечатки или использовать текст повторно. Сложную вёрстку, возможно, придётся подправить, а в отсканированном PDF, где только изображения страниц, извлекать нечего.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee сам проходит путь PDF → Word → EPUB, и текст подстраивается под экран телефона или читалки. Лучше всего это работает с PDF, в которых есть настоящий текст. Заголовки становятся обычными абзацами, а в отсканированных страницах конвертировать нечего.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee переносит текст PDF в документ Word, записывает его как HWPX, а затем сохраняет в HWP — всё встроенными движками. Это работает для PDF с настоящим текстом. Сложную вёрстку, возможно, придётся подправить, а из отсканированных страниц извлекать нечего.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee сначала превращает PDF в документ Word, а затем в Markdown, сохраняя абзацы, заголовки и жирный текст там, где может их различить. Пригодится для заметок, вики или чтобы вставить текст в другие инструменты. В отсканированных страницах конвертировать нечего.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Корейским учреждениям часто нужны документы в формате Hangul. Filee превращает текст PDF в файл HWPX, который можно открыть и править в Hancom Hangul, а для самой конвертации Hancom Office не нужен; если бланк требует старый формат, потом сконвертируйте в HWP.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Удобно, когда PDF нужно показать в PowerPoint или добавить в готовую презентацию: каждая страница становится слайдом, который выглядит точно как PDF, а текст страницы ждёт в заметках докладчика. Слайды — это картинки, так что, чтобы изменить текст, конвертируйте PDF в DOCX.`],

  // Conversion guides: documents
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Microsoft Word и LibreOffice не нужны: Filee сам читает DOCX и верстает страницы с колонтитулами, таблицами и картинками. Отпустите несколько документов на пресет «Объединить PDF», чтобы собрать их в один PDF.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Старые документы Word 97–2003 из архивов, официальных бланков или устаревших систем превращаются в PDF, которые откроются где угодно. Тот же движок конвертирует и файлы ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord и Apple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Сохраняйте письма в PDF для архива, отчётности или юридических документов: в PDF видны отправитель, получатели, дата, тема и текст, и он открывается где угодно без почтовой программы.`],

  // Conversion guides: HWP
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee отрисовывает страницы HWP движком rhwp с открытым кодом, так что ни Hancom Office, ни его запросы на подтверждение не участвуют. Пригодится, чтобы отправлять корейские документы тем, кто не может открыть HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Превратите документ Hangul в файл Word, который смогут править коллеги за рубежом. Текст, абзацы и таблицы переносятся; вёрстку с множеством плавающих объектов стоит быстро проверить в Word.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `HWPX, более новый формат Hangul на основе XML, конвертируется так же, как HWP: встроенный движок rhwp верстает страницы полностью офлайн. Удобно, чтобы архивировать бланки HWPX от госучреждений в PDF.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Некоторые системы и новые процессы принимают только HWPX. Filee конвертирует двоичный HWP в HWPX с помощью rhwp, без Hancom Office, и за один раз обрабатывает целую пачку старых документов.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Старые версии Hangul и некоторые порталы для подачи документов до сих пор ждут .hwp. Filee конвертирует HWPX обратно в HWP с помощью rhwp, так что не нужно открывать и пересохранять каждый файл в Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `Собственный модуль записи HWPX в Filee переносит вёрстку Word: размер страницы и поля, колонтитулы с номерами страниц, таблицы с объединёнными ячейками, границами и заливкой, текстовые поля, фигуры и картинки. Каждый записанный им файл в тестах проверяется тремя независимыми программами чтения HWPX.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Для учреждений и бланков, которые всё ещё требуют .hwp. Filee записывает документ Word в HWPX собственным модулем и конвертирует его в HWP с помощью rhwp — оба встроены, так что для конвертации Hancom Office не нужен.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Каждая страница документа Word становится JPG (сначала Filee верстает документ в PDF) — удобно, чтобы выложить страницу в сеть или быстро отправить превью. Word не нужен.`],

  // Conversion guides: spreadsheets
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Каждый видимый лист становится отдельным разделом с числовыми форматами, шрифтами, заливкой, границами и объединёнными ячейками — так, как их показывает Excel. Широкие листы масштабируются по ширине страницы, как с параметром Excel «Вписать все столбцы на одну страницу», а закреплённые строки заголовка повторяются на каждой странице.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `В CSV помещается одна таблица, поэтому Filee записывает по одному CSV на лист. Ячейки выгружаются значениями — готово для баз данных, скриптов и форм импорта.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `В книге XLSX есть место для форматирования, формул и дополнительных листов, которых нет в CSV. Выделите все выгрузки CSV и отпустите их разом — получите по книге на файл без мастера импорта Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Обновите старые книги Excel 97–2003 без Excel и LibreOffice: конвертация встроена. Файлы XLSX обычно меньше, не могут содержать макросы и открываются в любой современной табличной программе.`],

  // Conversion guides: presentations
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Каждый слайд становится страницей PDF размером со слайд — с текстом, фигурами, картинками, таблицами и оформлением образца. Удобно, чтобы раздать презентацию или загрузить её туда, где не принимают файлы PowerPoint. Анимация и заметки докладчика в PDF не попадают.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Старые презентации PowerPoint 97–2003 превращаются в PDF, которые любой может открыть, распечатать или загрузить. Презентации Keynote (.key), ODP и WPS (DPS) конвертируются так же.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Каждый слайд становится JPG — для постов в соцсетях, превью, сообщений в чате или видеоредактора. Если на слайдах много мелкого текста, лучше выберите PNG.`],

  // Conversion guides: text
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Заголовки, списки (в том числе списки задач), таблицы, код, цитаты, ссылки, картинки, сноски и формулы верстаются на страницах A4 без Pandoc, LaTeX и браузера. Быстрый способ поделиться заметками и файлами README с теми, кто не читает Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Встроено, Pandoc не нужен. Заголовки, списки, таблицы, ссылки и сноски переносятся, так что документ можно дальше править и оформлять в Word.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Простой текст превращается в аккуратный PDF формата A4, по абзацу на строку. Filee распознаёт UTF-8 и UTF-16, а также старые корейские текстовые файлы (CP949), так что старые журналы и заметки не превращаются в кракозябры.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Сохраните веб-страницу или HTML-отчёт в PDF, который везде выглядит одинаково и годится для архива или печати. Filee конвертирует файлы .html, сохранённые на компьютере, и несколько из них можно объединить в один PDF.`],

  // Conversion guides: e-books
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `В PDF вёрстка страниц фиксирована — это удобно, чтобы распечатать электронную книгу, читать её на компьютере или отправить на устройство без программы для EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Переведите старую библиотеку Kindle/Mobipocket в EPUB, чтобы она открывалась в Apple Books, Google Play Книгах, Kobo и большинстве приложений для чтения. Это направление встроено, Calibre не нужен.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `Файлы MOBI и AZW3 записывает Calibre, программа для электронных книг. Современные Kindle принимают и EPUB через Send to Kindle, так что MOBI нужен в основном для старых устройств и приложений Kindle.`],

  // Conversion guides: video
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Сохраните звук лекции, концерта или интервью в MP3, который играет везде: в машине, на старом плеере или в программе для расшифровки.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `Видео с iPhone и Mac — это файлы MOV. В MP4 они воспроизводятся на телефонах с Android, смарт-телевизорах, в старых программах Windows и проходят через формы загрузки, которые не принимают MOV. Видео и звук обычно подходят для MP4 как есть, поэтому Filee их только перепаковывает: без потери качества, с сохранением HDR, за секунды. Пресет MP4 720p уменьшает ролики 4K, чтобы ими было удобно делиться.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Записи MKV, например из OBS, часто не импортируются в видеоредакторы и не играют на телевизорах, а MP4 принимают почти везде. Конвертация идёт локально, так что длинные записи никуда загружать не нужно.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Записи экрана и видео, сохранённые из браузера, часто в WebM, с которым многие видеоредакторы, старые плееры и мессенджеры справляются плохо. MP4 играет почти везде, а целая пачка роликов конвертируется за раз.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Превратите короткий ролик в анимированный GIF для чата, документации или отчёта об ошибке. Делайте его коротким: GIF хранит каждый кадр как картинку в 256 цветах, поэтому длинные видео или видео в высоком разрешении дают очень большие файлы.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Видео, отпущенное на JPG, даёт один стоп-кадр. Чтобы выбрать превью или пройти ролик кадр за кадром, используйте пресет «Кадры в картинки (JPG)»: картинки попадут в папку рядом с видео — каждый кадр или каждый N-й. Видео, из которого получилось бы больше 100 000 картинок или которое заполнило бы диск, отклоняется ещё до начала.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `Файлы AVI со старых видеокамер и фотоаппаратов большие и часто используют кодеки, которые телефоны и телевизоры уже не воспроизводят. MP4 с современным сжатием обычно намного меньше и играет везде.`],

  // Conversion guides: audio
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Запись в WAV занимает около 10 МБ в минуту; в MP3 ей хватает малой доли этого места, и она по-прежнему играет на любом устройстве.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Храните библиотеку FLAC без потерь дома, а копии в MP3 закиньте на телефон, флешку для машины или старый плеер, который не понимает FLAC. Целые альбомы конвертируются за один раз.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `Диктофон iPhone, покупки в iTunes без DRM и многие рекордеры дают файлы M4A. MP3 принимает любой плеер, автомагнитола и форма загрузки.`],

  // Conversion guides: archives
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Перепакуйте архивы RAR в ZIP для людей, форм загрузки и систем, которые принимают только ZIP. WinRAR не нужен ни для чтения RAR, ни для записи ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `7Z часто сжимает лучше, но ZIP открывается на любом компьютере и телефоне без дополнительных программ. Конвертируйте, когда отправляете архив тому, у кого нет 7-Zip.`],

  // Conversion guides: CAD
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Отправляйте чертежи заказчикам, прорабам или в типографию, где нет AutoCAD: PDF откроется на любом компьютере и телефоне. Несколько чертежей можно объединить в один PDF.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `Файлы DXF из CAD-программ, заказов на лазерную резку или обмена проектами превращаются в PDF, которые любой может открыть и распечатать. Доступны также SVG и PNG, например для превью на сайте.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF — формат обмена, который читают лазерные резаки, программы ЧПУ и большинство CAD-программ. Конвертация DWG в DXF позволяет открыть чертежи AutoCAD в этих инструментах, и обратно, из DXF в DWG, тоже работает.`],

  // Conversion guides: fonts
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Разместите шрифт на своём сайте: WOFF2 — сжатый формат веб-шрифтов, который поддерживает любой современный браузер, обычно примерно на 30 % меньше WOFF. Проверьте, разрешает ли лицензия шрифта встраивание на сайт.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Некоторые старые программы, режущие плоттеры, вышивальные машины и игровые движки принимают только шрифты TrueType. Сконвертируйте целое семейство шрифтов OTF в TTF за один раз, без редактора шрифтов.`],

  // Conversion guides: tracing and SVG → CAD
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Для логотипов, подписей и сканов используйте «Штриховой рисунок в SVG»: чернила становятся одной чёрной фигурой на прозрачном фоне. «Обвести в SVG» сохраняет до 64 цветов — для значков и иллюстраций. Фото превращаются в плоские пятна, так что обводка лучше всего подходит для рисунков.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `JPG с логотипом или отсканированный эскиз превращается в SVG, чёткий в любом размере, — для режущего плоттера, сайта или типографии. Шум JPG превращается в крапинки, так что, если результат выглядит перегруженным, уменьшите в пресете «Детализацию».`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Лазерные резаки, программы ЧПУ и CAD-программы читают DXF. Filee записывает контуры SVG в миллиметрах, так что фигура шириной 100 мм остаётся 100 мм. Кривые становятся мелкими полилиниями. Заливки, картинки и фильтры не переносятся.`],

  // Conversion guides: e-mail
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Письма, перетащенные из Outlook, — это файлы MSG, которые открывает только Outlook. В PDF сохраняются отправитель, получатели, дата, тема и текст, и файл открывается где угодно. Outlook не нужен.`],

  // Conversion guides: data
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML проще читать и править вручную, поэтому его и используют для конфигураций. Ключи сохраняют порядок, а текст, который при обратном чтении стал бы числом или true/false, берётся в кавычки.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Превратите конфигурацию в JSON для API, скрипта или инструмента, который читает только JSON. Якоря и псевдонимы раскрываются, а файл с несколькими документами становится одним массивом. Комментарии отбрасываются: в JSON их нет.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Список записей в JSON становится таблицей, которую можно открыть в Excel: строка на запись, столбец на ключ. Обёртка вида {"users": […]} пропускается. Если данные не табличные, конвертация остановится с сообщением, а не выдаст испорченный файл.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Перенесите адресную книгу в Excel или сервис рассылок: строка на контакт с именем, организацией, почтой, телефоном, адресом и днём рождения. Контакты со старых корейских телефонов в CP949 читаются правильно.`],

  // Conversion guides: subtitles
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Веб-плееры и платформы онлайн-курсов хотят WebVTT. Тайминг, переносы строк и курсив сохраняются, движок не нужен.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Многие плееры, телевизоры и редакторы не читают SMI, а старые корейские файлы SMI часто показываются кракозябрами. Filee распознаёт CP949, выбирает язык, в котором больше всего строк, и сохраняет чистый SRT в UTF-8.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Когда телевизор, телефон или видеосайт не принимает оформленные субтитры ASS, выручит простой SRT. Жирный, курсив, подчёркивание и цвета сохраняются; позиции, шрифты и эффекты отбрасываются.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Достаньте субтитры из фильма, чтобы отредактировать или перевести их. Первая текстовая дорожка субтитров сохраняется в SRT; графические субтитры (DVD, Blu-ray) в текст превратить нельзя. Нужен бесплатный движок FFmpeg.`],

  // Conversion guides: 3D models
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Откройте файл для печати в 3D-программе, которая предпочитает OBJ. В STL нет единиц измерения, поэтому Filee читает его в миллиметрах и в миллиметрах же записывает OBJ, с осью Y вверх, как в большинстве 3D-программ.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Слайсеры для 3D-принтеров принимают STL. Грани любой формы разбиваются на треугольники, а ось Y вверх становится осью Z вверх, так что стоящая модель стоит на столе принтера. STL хранит только форму, поэтому цвета и текстуры остаются в OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Перенесите модель из веба или игрового движка в программу, которая читает OBJ. Файл .mtl и текстуры записываются рядом с .obj, так что держите их вместе.`],

  // FAQ
  [`Is Filee really free?`,
    `Filee действительно бесплатный?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Да. Filee бесплатный и с открытым кодом под лицензией MIT: без рекламы, водяных знаков, аккаунта и пробного периода, без собственных ограничений на число и размер файлов.`],
  [`Does it work offline? Are my files uploaded?`,
    `Он работает офлайн? Мои файлы куда-то загружаются?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Каждая конвертация выполняется на вашем компьютере, и файлы никуда не загружаются. Интернет нужен только для загрузки дополнительного движка или проверки обновлений, так что конфиденциальные документы, фото и записи остаются у вас.`],
  [`Which file formats does Filee support?`,
    `Какие форматы файлов поддерживает Filee?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee читает {formatTotal|one:# формат|few:# формата|many:# форматов|other:# формата} файлов в {categoryCount|one:# категории|other:# категориях}: {categoryList}. {builtinTotal|one:# из них работает|few:# из них работают|many:# из них работают|other:# из них работает} сразу после установки; для остальных нужен бесплатный дополнительный движок. В каталоге форматов перечислены все форматы и то, во что каждый из них конвертируется.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Нужны ли Microsoft Office, Hancom Office или LibreOffice?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF.`,
    `Нет. Файлы Word, Excel и PowerPoint (DOCX, XLSX, XLS, CSV, PPTX) и корейские документы HWP/HWPX конвертируют движки, встроенные в Filee. Filee не использует Office и Hancom Office, даже если они установлены; LibreOffice — лишь дополнительная загрузка в программе для старых форматов вроде DOC, PPT, ODT и RTF.`],
  [`What are the optional engines?`,
    `Что такое дополнительные движки?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Большие движки не входят в установщик. Отметьте их на странице движков в установщике или скачайте в Filee, когда понадобятся: {engineDetails}. Они хранятся в собственной папке Filee и удаляются в любой момент, а программа показывает их версии, скорость загрузки и оставшееся время. Если FFmpeg, calibre, Pandoc, Ghostscript или LibreOffice уже есть на компьютере (в PATH, в том числе через Scoop, или в Program Files), Filee использует его и ничего не скачивает, а если эта копия старше версии, с которой Filee проверен, предупредит об этом. Конкретную копию можно выбрать в Настройки → Движки → Использовать свою копию.`],
  [`Does installing Filee need administrator rights?`,
    `Нужны ли для установки Filee права администратора?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Только один раз, при установке. Установщик ставит Filee в Program Files для всех пользователей, а в Windows 11 добавляет «Конвертировать с Filee» в верхний уровень меню Проводника. Сам Filee потом работает с правами обычного пользователя. Если устанавливать программы нельзя, возьмите портативный ZIP: распакуйте его куда угодно и запустите Filee.exe.`],
  [`Can I convert many files at once?`,
    `Можно ли конвертировать много файлов сразу?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Да. Выделите сколько угодно файлов и отпустите их разом: Filee конвертирует их параллельно, ошибка в одном файле не останавливает остальные, а пресеты могут объединить всё в один PDF или упаковать в один ZIP.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `Можно ли конвертировать из контекстного меню Windows 11?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Да. Щёлкните файлы правой кнопкой в Проводнике и выберите «Конвертировать с Filee». В Windows 11 этот пункт можно вынести и в основное меню, без «Показать дополнительные параметры»: один раз нажмите «Добавить в основное меню» в Настройки → Общие и подтвердите запрос администратора. Работают и меню «Отправить», и горячая клавиша, и зона перетаскивания в главном окне.`],
  [`Can Filee convert from the command line or automatically?`,
    `Может ли Filee конвертировать из командной строки или автоматически?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Да. Установщик может добавить команду filee в PATH: filee convert *.heic --to jpg конвертирует файлы, маски и папки с вашими пресетами, выводит JSON для скриптов и возвращает коды завершения. Папки наблюдения автоматически конвертируют попадающие в них файлы и могут откладывать оригиналы в сторону. Настройте их на странице «Папки наблюдения» в программе или командой filee watch в терминале.`],
  [`How do I convert a file, for example HEIC to JPG?`,
    `Как сконвертировать файл, например HEIC в JPG?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Выделите файлы в Проводнике, зажмите Ctrl (или выбранную вами клавишу) и перетащите их. У курсора откроется круг форматов: отпустите файлы на JPG, и новые файлы появятся рядом с оригиналами. Для самых частых конвертаций есть пошаговые руководства.`],
  [`Why use Filee instead of an online converter?`,
    `Почему Filee, а не онлайн-конвертер?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Онлайн-конвертеры загружают ваши файлы на чужой сервер, часто ограничивают размер и количество файлов и зависят от быстрого интернета. Filee конвертирует на вашем компьютере: личные файлы остаются личными, большие видео и сотни файлов — не проблема, и всё работает без интернета, бесплатно и без рекламы.`],
  [`Which operating systems are supported?`,
    `Какие операционные системы поддерживаются?`],
  [`Windows 10 and 11 (64-bit) is the stable release. macOS 14 or later (Apple silicon and Intel) and Linux (x64 and ARM64) are previews: the macOS app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security, and on Linux the drag gesture needs an X11 session (on Wayland, use the drop zone and the right-click action). Pick your system in the download section.`,
    `Стабильная версия — для Windows 10 и 11 (64-бит). macOS 14 и новее (Apple Silicon и Intel) и Linux (x64 и ARM64) — предварительные версии: приложение для macOS пока не нотаризовано, поэтому macOS один раз попросит разрешить его в разделе «Конфиденциальность и безопасность», а в Linux жесту перетаскивания нужна сессия X11 (в Wayland пользуйтесь зоной перетаскивания и действием в контекстном меню). Выберите свою систему в разделе загрузки.`],
]);
